//! Cross-crate regression ("golden dataset") tests: fixed inputs, pinned
//! numeric outputs (see `tests` crate's `src/lib.rs` for why these are
//! distinct from external validation). Reference values below were
//! generated by this engine itself and are regression baselines, not
//! externally validated figures — external validation is the scope of the
//! (currently unimplemented) `validation` crate.

use core_math::julian::CalendarDateTime;
use core_units::{Angle, Irradiance, Pressure, Ratio, Temperature, Velocity};
use simulation::{
    EnergyBalanceInput, ThermalModel, TranspositionModel, WeatherInput, compute_energy_balance,
};
use solar_geometry::incidence::SurfaceOrientation;
use solar_position::{self, AtmosphericConditions, Observer};
use thermal_model::sandia::SandiaMountingCoefficients;

fn reference_site_input(transposition_model: TranspositionModel) -> EnergyBalanceInput {
    EnergyBalanceInput {
        datetime_utc: CalendarDateTime {
            year: 2024,
            month: 6,
            day: 21,
            hour: 11,
            minute: 0,
            second: 0.0,
        },
        observer: Observer {
            latitude: Angle::from_degrees(45.188),
            longitude: Angle::from_degrees(5.724),
            elevation: core_units::Length::from_meters(212.0),
        },
        atmosphere: AtmosphericConditions {
            pressure: Pressure::from_hectopascal(1013.25),
            temperature: Temperature::from_celsius(22.0),
        },
        surface: SurfaceOrientation {
            tilt: Angle::from_degrees(35.0),
            azimuth: Angle::from_degrees(180.0),
        },
        ground_albedo: Ratio::new(0.2),
        weather: WeatherInput {
            ghi: Irradiance::from_watts_per_m2(823.0),
            dni: None,
            dhi: None,
            ambient_temperature: Temperature::from_celsius(26.0),
            wind_speed: Velocity::from_meters_per_second(2.5),
        },
        transposition_model,
        thermal_model: ThermalModel::Sandia {
            coefficients: SandiaMountingCoefficients::OPEN_RACK_GLASS_GLASS,
        },
    }
}

/// Regression baseline: Grenoble-area site (45.188N, 5.724E), 2024-06-21
/// 11:00 UTC (near the June solstice), 35 deg tilt / due South, GHI-only
/// weather input (Erbs decomposition exercised), Perez transposition,
/// Sandia open-rack thermal model. Reference values captured directly from
/// this engine's own output (see the module doc). Any change to this
/// output must be a reviewed, intentional change to the underlying model,
/// not a side effect of an unrelated refactor.
#[test]
fn golden_dataset_grenoble_summer_perez() {
    let input = reference_site_input(TranspositionModel::Perez);
    let result = compute_energy_balance(input).unwrap();

    assert!(
        (result.solar_position.zenith_true.degrees() - 23.1539).abs() < 0.01,
        "zenith_true = {}",
        result.solar_position.zenith_true.degrees()
    );
    assert!(
        (result.solar_position.azimuth.degrees() - 156.708).abs() < 0.01,
        "azimuth = {}",
        result.solar_position.azimuth.degrees()
    );
    assert!(
        (result.poa.global.watts_per_m2() - 886.372).abs() < 0.5,
        "poa.global = {}",
        result.poa.global.watts_per_m2()
    );
    assert!(
        (result.cell_temperature.celsius() - 49.557).abs() < 0.1,
        "cell_temperature = {}",
        result.cell_temperature.celsius()
    );
}

/// Same scenario evaluated with all four transposition models: they must
/// agree with each other within a physically reasonable spread (they are
/// different approximations of the same sky, not unrelated quantities),
/// which also guards against a wiring mistake sending the wrong model's
/// output through the pipeline.
///
/// The observed spread here (isotropic lowest, Perez highest, ~5%) is
/// physically expected, not a defect: this scenario has a small angle of
/// incidence (the surface is tilted almost directly towards the Sun near
/// solar noon at the summer solstice) under a moderately clear sky, which
/// is exactly the condition where circumsolar-brightening models (Hay-
/// Davies, HDKR, Perez) are known to diverge most from the plain isotropic
/// model — a well-documented effect (e.g. Duffie & Beckman (2013), Section
/// 2.16, comparative discussion of tilted-surface radiation models).
#[test]
fn all_transposition_models_agree_within_a_reasonable_spread() {
    let mut results = Vec::new();
    for model in [
        TranspositionModel::Isotropic,
        TranspositionModel::HayDavies,
        TranspositionModel::Hdkr,
        TranspositionModel::Perez,
    ] {
        let input = reference_site_input(model);
        let result = compute_energy_balance(input).unwrap();
        results.push(result.poa.global.watts_per_m2());
    }

    let min = results.iter().cloned().fold(f64::MAX, f64::min);
    let max = results.iter().cloned().fold(f64::MIN, f64::max);
    let spread_fraction = (max - min) / min;
    assert!(
        spread_fraction < 0.08,
        "transposition models disagree by {:.2}% ({:?})",
        spread_fraction * 100.0,
        results
    );
}

/// End-to-end sanity: a full day sweep (hourly) must never produce
/// non-finite output, and plane-of-array irradiance must be zero whenever
/// the Sun is below the horizon and positive around midday, for every
/// transposition model. This is a robustness regression test, not a
/// precision one.
///
/// Weather input is derived self-consistently at each hour (GHI is zeroed
/// whenever the Sun is below the horizon, exactly as a real ground
/// pyranometer would read): feeding a nonzero GHI while the Sun is below
/// the horizon is a physically invalid input (GHI cannot exceed the
/// extraterrestrial horizontal irradiance, which is itself zero at
/// night), and the engine's decomposition step is not expected to produce
/// a sensible split for a self-contradictory input.
#[test]
fn full_day_sweep_is_finite_and_physically_sane_for_every_model() {
    for model in [
        TranspositionModel::Isotropic,
        TranspositionModel::HayDavies,
        TranspositionModel::Hdkr,
        TranspositionModel::Perez,
    ] {
        let mut saw_positive_daytime_poa = false;
        for hour in 0..24u32 {
            let mut input = reference_site_input(model);
            input.datetime_utc.hour = hour;

            let position = solar_position::solar_position(
                input.datetime_utc,
                input.observer,
                input.atmosphere,
            )
            .unwrap();
            let is_daytime = position.elevation_true.degrees() > 0.0;
            if !is_daytime {
                input.weather.ghi = Irradiance::ZERO;
            }

            let result = compute_energy_balance(input).unwrap();

            assert!(result.poa.global.watts_per_m2().is_finite());
            assert!(result.cell_temperature.celsius().is_finite());
            assert!(result.poa.global.watts_per_m2() >= 0.0);

            if !is_daytime {
                assert_eq!(
                    result.poa.global.watts_per_m2(),
                    0.0,
                    "hour={hour}, model={model:?}"
                );
            } else if result.poa.global.watts_per_m2() > 100.0 {
                saw_positive_daytime_poa = true;
            }
        }
        assert!(saw_positive_daytime_poa, "model={model:?}");
    }
}
